import os, json, sys, math

# Physical constants (SI)
G = 6.67430e-11          # m^3 kg^-1 s^-2
c = 2.99792458e8        # m s^-1
hbar = 1.054571817e-34  # J s
k_B = 1.380649e-23      # J K^-1
M_sun = 1.98847e30      # kg

def hawking_temperature(M):
    """Return Hawking temperature for a non-rotating BH of mass M (kg)."""
    return hbar * c**3 / (8.0 * math.pi * G * k_B * M)

def main():
    catalog_path = os.getenv('GWTC_CATALOG_PATH')
    if not catalog_path:
        print('Error: GWTC_CATALOG_PATH environment variable not set.')
        sys.exit(1)
    try:
        with open(catalog_path, 'r') as f:
            data = json.load(f)
    except Exception as e:
        print(f'Error reading catalog: {e}')
        sys.exit(1)
    events = data.get('events', [])
    if not events:
        print('Error: No events found in the catalog.')
        sys.exit(1)
    violations = []
    for ev in events:
        m1 = ev.get('mass_source1') or ev.get('mass_object1')
        m2 = ev.get('mass_source2') or ev.get('mass_object2')
        if m1 is None or m2 is None:
            continue
        try:
            M1 = float(m1) * M_sun
            M2 = float(m2) * M_sun
        except (ValueError, TypeError):
            continue
        if M1 <= 0 or M2 <= 0:
            continue
        T1 = hawking_temperature(M1)
        T2 = hawking_temperature(M2)
        if T1 > 1e-22 or T2 > 1e-22:
            violations.append((ev.get('event', '<unknown>'), T1, T2))
    if not violations:
        print('All events satisfy T_H \le 1e-22 K.')
    else:
        print('Violations found:')
        for name, T1, T2 in violations:
            print(f"  {name}: T_H = {T1:.3e} K, T_H = {T2:.3e} K")

if __name__ == '__main__':
    main()

